package kw.urtv.home;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.view.*;import android.widget.*;import kw.urtv.shared.*;

/** Two native first-run pages. No web renderer, downloads, worker or resident service. */
public class SetupActivity extends Activity {
 private kw.urtv.shared.Place place;private int step,region,reading;private String theme;private LinearLayout controls;private Typeface font;private boolean dark;private int ink,muted;
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().getDecorView().setSystemUiVisibility(5894);place=kw.urtv.shared.Place.load(this);font=Typeface.createFromAsset(getAssets(),"fonts/Thmanyah-Medium.otf");region=Dock.prefs(this).getInt("setup_region",0);if(region<0||region>=RegionCatalog.ALL.length)region=0;reading=DisplayOptions.load(this).reading;theme=DisplayOptions.load(this).theme;if(state!=null){try{place=Place.parse(state.getString("place"));}catch(Exception ignored){}step=state.getInt("step");region=state.getInt("region",region);reading=state.getInt("reading",reading);theme=state.getString("theme",theme);}render();}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("place",place.json());b.putInt("step",step);b.putInt("region",region);b.putInt("reading",reading);b.putString("theme",theme);}
 private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
 private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(font);t.setGravity(Gravity.RIGHT);t.setTextDirection(View.TEXT_DIRECTION_RTL);return t;}
 private TextView button(String label,Runnable action){TextView t=text(label,19,ink);t.setGravity(Gravity.CENTER);t.setPadding(dp(14),dp(9),dp(14),dp(9));t.setFocusable(true);t.setFocusableInTouchMode(true);t.setClickable(true);t.setMinHeight(dp(46));GradientDrawable bg=new GradientDrawable();bg.setCornerRadius(dp(10));bg.setColor(dark?0xFF2D393D:0xFFFFFFFF);bg.setStroke(dp(1),dark?0xFF667874:0xFFB5C3BF);t.setBackground(bg);t.setOnFocusChangeListener((v,f)->{bg.setColor(f?(dark?0xFFE0EDE8:0xFF284A43):(dark?0xFF2D393D:0xFFFFFFFF));t.setTextColor(f?(dark?0xFF152724:0xFFFFFFFF):ink);});t.setOnClickListener(v->action.run());return t;}
 private void add(String label,Runnable action){TextView b=button(label,action);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(10);controls.addView(b,p);}
 private void render(){dark=theme.equals("dark")||(theme.equals("auto")&&(getResources().getConfiguration().uiMode&48)==32);ink=dark?0xFFF3F5F3:0xFF23352F;muted=dark?0xFFBACAC4:0xFF53665D;LinearLayout root=new LinearLayout(this);root.setOrientation(android.widget.LinearLayout.VERTICAL);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.setBackgroundColor(dark?0xFF182224:0xFFF0F3F0);root.setPadding(dp(48),dp(22),dp(48),dp(22));setContentView(root);root.addView(text(step==0?"إعداد الشاشة                       ١ من ٢":"إعداد الشاشة                       ٢ من ٢",15,muted));LinearLayout body=new LinearLayout(this);body.setGravity(Gravity.CENTER_VERTICAL);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));LinearLayout story=new LinearLayout(this);story.setOrientation(android.widget.LinearLayout.VERTICAL);story.setPadding(dp(12),0,dp(28),0);body.addView(story,new LinearLayout.LayoutParams(0,-2,1));story.addView(new Diagram(),new LinearLayout.LayoutParams(-1,dp(145)));story.addView(text("صلاتك، في وقتها.",32,ink));story.addView(text("مواقيت الصلاة والطقس حسب مدينتك",17,muted));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body.addView(scroll,new LinearLayout.LayoutParams(0,-1,1.25f));controls=new LinearLayout(this);controls.setOrientation(android.widget.LinearLayout.VERTICAL);controls.setGravity(Gravity.CENTER_VERTICAL);controls.setPadding(dp(12),dp(14),dp(12),dp(10));scroll.addView(controls);controls.addView(text(step==0?"أين أنت؟":"كيف تحب شاشتك؟",29,ink));TextView intro=text(step==0?"اختر منطقتك لضبط الصلاة والطقس":"المظهر وحجم الكتابة",16,muted);intro.setPadding(0,0,0,dp(12));controls.addView(intro);
 if(step==0){add("الدولة والمدينة · "+place.name,()->startActivityForResult(new Intent(this,kw.urtv.shared.LocationPickerActivity.class).putExtra("place",place.json()),41));controls.addView(text("طريقة المواقيت · "+place.label(),16,muted));add("التالي",()->{step=1;render();});}
 else{add("مظهر التطبيق · "+(theme.equals("dark")?"داكن":theme.equals("light")?"فاتح":"تلقائي"),()->new AlertDialog.Builder(this,dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setTitle("مظهر التطبيق").setSingleChoiceItems(new String[]{"فاتح","داكن","تلقائي"},theme.equals("light")?0:theme.equals("dark")?1:2,(d,n)->{theme=new String[]{"light","dark","auto"}[n];d.dismiss();render();}).show());add("حجم الكتابة · "+new String[]{"عادي","كبير","أكبر"}[reading],()->new AlertDialog.Builder(this,dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setTitle("حجم الكتابة").setSingleChoiceItems(new String[]{"عادي","كبير","أكبر"},reading,(d,n)->{reading=n;d.dismiss();render();}).show());add("تخصيص التطبيقات والريموت · اختياري",()->startActivity(new Intent(this,CustomizationActivity.class)));LinearLayout row=new LinearLayout(this);TextView save=button("ابدأ",this::save),back=button("السابق",()->{step=0;render();});row.addView(save,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,-2,1);bp.rightMargin=dp(10);row.addView(back,bp);controls.addView(row);}
 for(int i=0;i<controls.getChildCount();i++)if(controls.getChildAt(i).isFocusable()){controls.getChildAt(i).requestFocus();break;}}
 private void save(){RegionCatalog.Region r=RegionCatalog.ALL[region];ContentValues values=new ContentValues();values.put("place",place.json());try{if(getContentResolver().update(DisplayOptions.URI,values,null,null)!=1)throw new IllegalStateException();}catch(Exception e){new AlertDialog.Builder(this,dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setTitle("تعذر حفظ المنطقة").setMessage("ثبّت النسخة المرافقة من شاشة التوقف ثم حاول مجددًا.").setPositiveButton("حسنًا",null).show();return;}DisplayOptions options=DisplayOptions.load(this);options.reading=reading;options.theme=theme;options.save(this);Dock.prefs(this).edit().putInt("setup_region",region).putString("setup_theme",theme).putBoolean("setup_complete",true).apply();startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));finish();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==41&&result==RESULT_OK&&data!=null){try{place=Place.parse(data.getStringExtra("place"));render();}catch(Exception ignored){}}}
 @Override public void onBackPressed(){if(step==1){step=0;render();}else if(Dock.prefs(this).getBoolean("setup_complete",false))finish();else new AlertDialog.Builder(this,dark?android.R.style.Theme_Material_Dialog_Alert:android.R.style.Theme_Material_Light_Dialog_Alert).setMessage("اختر منطقتك ثم اضغط التالي لإكمال الإعداد.").setPositiveButton("حسنًا",null).show();}
 private class Diagram extends View{Paint p=new Paint(3);Diagram(){super(SetupActivity.this);setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);}@Override protected void onDraw(Canvas c){float s=Math.min(getWidth()/300f,getHeight()/150f);c.save();c.scale(s,s);p.setColor(ink);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);c.drawRoundRect(10,8,280,125,10,10,p);c.drawLine(145,125,145,140,p);c.drawLine(110,140,180,140,p);p.setStyle(Paint.Style.FILL);for(int i=0;i<4;i++)c.drawRoundRect(180,30+i*18,260,36+i*18,3,3,p);p.setAlpha(90);c.drawRoundRect(30,30,120,43,4,4,p);for(int i=0;i<3;i++)c.drawRoundRect(35+i*45,92,70+i*45,113,5,5,p);p.setAlpha(255);c.restore();}}
}
